import{_ as p,c as e,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"22、【賁】 離下艮上","description":"周易闡真 - 22、【賁】 離下艮上","frontmatter":{"title":"22、【賁】 離下艮上","description":"周易闡真 - 22、【賁】 離下艮上"},"headers":[],"relativePath":"classics/chanzhen/023.md","filePath":"classics/chanzhen/023.md"}'),s={name:"classics/chanzhen/023.md"};function n(c,a,i,o,l,h){return t(),e("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：賁亨，柔來而文剛，故亨。分，剛上而文柔，故小利有攸往。剛柔交錯，天文也。文明以止，人文也。觀乎天文，以察時變；觀乎人文，以化成天下。</p></blockquote><h1 id="_22、【賁】-離下艮上" tabindex="-1">22、【賁】 離下艮上 <a class="header-anchor" href="#_22、【賁】-離下艮上" aria-label="Permalink to “22、【賁】 離下艮上”">​</a></h1><p>初九：賁其趾，舍車而徒。</p><p>六二：賁其須。</p><p>九三：賁如濡如，永貞吉。</p><p>六四：賁如皤如，白馬翰如。匪寇，婚媾。</p><p>六五：賁於丘園，束帛戔戔。吝，終吉。</p><p>上九：白賁，無咎。</p><h2 id="孔易闡真-​" tabindex="-1">孔易闡真 ​ <a class="header-anchor" href="#孔易闡真-​" aria-label="Permalink to “孔易闡真 ​”">​</a></h2><p>大象：山下有火，賁。君子以明庶政，無敢折獄。</p><p>賁者，飾也。上艮山，下離火，是山下有火也。山下有火，而凡山下之物，皆霑其光，以火照山，賁之象也。</p><p>君子有見於此，知山下之火，其光不大，人之才缺，其見不遠，以是於庶政之易事而修明之，於折獄之難事無敢強焉。庶政，即風俗利弊、錢穀詞訟之類。庶政之興廢，顯而易見，不難修治，即有錯誤，猶能更變。至於獄事，性命所關，幽隱難辨，稍有不明，殃及無辜，非智察秋毫者，不能折之。無敢折獄，亦重性命之意也。修道者之用明，亦不外此理。應世接物、日用常行之事，如庶政也；儘性至命、幽深奧妙之理，如獄事也。應世接物，人道也；儘性至命，天道也。人道顯而易見，稍有才智者，即能辨之。至於天道，必須真師口傳心授，大悟大徹，方能折辨不差，信手拈來，頭頭是道，利己兼能利人，為功最大。若無師傳，妄猜私議，而強折之，毫髮之差，千里之失，誤人性命，何敢折乎?無敢二字，是聖人教人養小明，而漸求其大明，不可恃小明而壞大事，自惑惑人也。噫!小智小慧之誤人甚矣。</p><h2 id="悟元子註解-​" tabindex="-1">悟元子註解 ​ <a class="header-anchor" href="#悟元子註解-​" aria-label="Permalink to “悟元子註解 ​”">​</a></h2><p>賁，音臂。舍，音捨。皤，白波反。戔，音箋。</p><p>賁者，文飭之義。卦德上艮止，下離明，明乎其所止，止於其所明，自明明德，而止於至善，故謂賁。此潛修密煉之卦，承上觀卦而來。觀者，隨時漸進，神明覺察之道，能覺能察，迴光返照，大智若愚，大巧若拙。止其明而明有養，明於止而止其所，明止相賁，明而不至於誤用，止而不落於空寂。止以明為體，明以止為用，明不傷而止得正，明之止之，未有不亨者也。</p><p>然雖明止相賁，尤必以止明為貴。止明，非空空無為，全不用明之謂，特明於內而不明於外，止於明而不止於不明，明在止中，不輕用明，自小之義也。自小，則戒慎恐懼，黜聰毀智，神明內守，虛靈不昧，一切外物不得而移之，其利居多。但太過於小，是止而不明，非本卦明止相合之象，如何得亨、得利乎?</p><p>夫所謂止者，止於至善，寂然不動也；所謂明者，明其明德，感而遂通也。靜則無為，動則有作，明於止而止行明，得於心而驗於事，方謂真止，方謂真明。辭曰“利有攸往”者，所以驗此止、驗此明耳。</p><p>凡人當無事之時，每心地明亮，知其所止；及至有事，即便昏迷，不知其所止矣。若能由明而止以養明，由止而明以通明，明止不拘，隨時而用，大火裡栽蓮，泥水中拖船，一靈妙有，法界圓通，明於止而其所當止矣。</p><p>初九，剛而能明，自卑自下，抱道而居，如賁其趾也。賁趾之剛，不以外假而傷內真，是以舍其車，而甘於徒行。此剛而守正之賁也。</p><p>六二，居於二陽之中，虛己求人，知其一己之明有限，眾人之明無窮，必有所須，而識見始能擴充。此柔而借剛之賁也。</p><p>九三，剛明太過，只知用明，不知虛明，明必不能達遠，是以賁如濡如也。幸其剛而得正，永久不變其所守，雖不能賁於外，而能賁於內，亦致吉之道。此剛而用明之賁也。</p><p>六四，居於上體，柔而不明，有應初陽，不恥下問，是以賁如皤如，白馬翰如，以不明而急求其明也。但以上求下，有挾貴自尊之嫌，多不誠信。幸其柔而得正，真心實意，出於自然，不是勉強，匪有寇傷，乃欲求其婚媾耳。此柔而求明之賁也。</p><p>六五，柔而不剛，執中無權，孤寂守靜，是以賁於丘園，束帛戔戔也。丘園者，曠遠無人之處，絕無人事可知；戔戔之帛，而又束之，絕無威儀可知。無人事、無威儀，過於澹泊，不近人情，乃修道者羞吝之事。然柔而得中，雖不明乎大道，亦不失為養靜之人，終得以吉全之。此柔而自得之賁也。</p><p>上九，剛柔相當，自明明德，而止於至善，不賁而賁，賁至於無色，是謂白賁也。賁而至白，明止如一，氣質俱化，渾然天理，而無一毫人慾之咎矣。此剛柔混合之賁也。</p><p>然則賁之為道，必以明止相需為貴。明於止而止其所，止其明而明不昧，明之止之，隨時而用，潛修密煉之功在是矣。</p>',25)])])}const m=p(s,[["render",n]]);export{d as __pageData,m as default};
